package network.velora.mobile;
import com.getcapacitor.*;
import com.getcapacitor.annotation.CapacitorPlugin;
import android.content.SharedPreferences;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import java.security.KeyStore;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import org.json.*;
@CapacitorPlugin(name="VeloraNative")
public class NativeApiPlugin extends Plugin {
 private SharedPreferences prefs;private volatile boolean online=false;private JSONObject features=new JSONObject();private final ExecutorService executor=Executors.newSingleThreadExecutor();private final java.util.Set<HttpURLConnection> connections=ConcurrentHashMap.newKeySet();
 @Override public void load(){prefs=getContext().getSharedPreferences("velora-native",0);try{JSONObject settings=new JSONObject(prefs.getString("network","{}"));online=settings.optBoolean("online",false);features=settings.optJSONObject("features");if(features==null)features=new JSONObject();}catch(Exception ignored){}}
 private boolean allowed(String key){return online&&(key.equals("identity")||features.optBoolean(key,!key.equals("browser")));}
 private SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("velora-session")){KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("velora-session",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (SecretKey)ks.getKey("velora-session",null);}
 private String token(){try{String saved=prefs.getString("session","");if(saved.isEmpty())return "";byte[] bytes=Base64.decode(saved,Base64.NO_WRAP);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOfRange(bytes,0,12)));return new String(c.doFinal(java.util.Arrays.copyOfRange(bytes,12,bytes.length)),StandardCharsets.UTF_8);}catch(Exception ignored){return "";}}
 private void saveToken(String token)throws Exception{if(token.isEmpty()){prefs.edit().remove("session").remove("profile").apply();return;}Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(c.getIV());out.write(c.doFinal(token.getBytes(StandardCharsets.UTF_8)));prefs.edit().putString("session",Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP)).apply();}
 @PluginMethod public void info(PluginCall call){JSObject result=new JSObject();String packageName=getContext().getPackageName();result.put("app",packageName.substring(packageName.lastIndexOf('.')+1));try{result.put("version",getContext().getPackageManager().getPackageInfo(packageName,0).versionName);}catch(Exception e){result.put("version","0.4.0");}call.resolve(result);}
 @PluginMethod public void configure(PluginCall call){online=Boolean.TRUE.equals(call.getBoolean("online",false));features=call.getObject("features",new JSObject());JSObject result=new JSObject();result.put("online",online);result.put("features",features);prefs.edit().putString("network",result.toString()).apply();for(HttpURLConnection c:connections)c.disconnect();IsolatedPageActivity.networkChanged(online,features.optBoolean("nexora",true));call.resolve(result);}
 @PluginMethod public void status(PluginCall call){JSObject result=new JSObject();result.put("online",online);result.put("features",features);call.resolve(result);}
 @PluginMethod public void request(PluginCall call){executor.execute(()->{HttpURLConnection connection=null;try{String path=call.getString("path","");String method=call.getString("method","GET");String feature=call.getString("feature","identity");if(!path.matches("/(?:v1/[a-zA-Z0-9_/?=&.%+-]+|health)")||path.startsWith("/v1/admin/")||!java.util.Arrays.asList("GET","POST","PUT","PATCH","DELETE").contains(method))throw new Exception("Unsupported request.");if(!online){if((path.equals("/v1/me")||path.equals("/v1/nomi/me"))&&!token().isEmpty()){JSObject cached=JSObject.fromJSONObject(new JSONObject(prefs.getString("profile","{}")));cached.put("offline",true);call.resolve(cached);return;}if(path.equals("/v1/auth/logout")){saveToken("");call.resolve(new JSObject().put("ok",true));return;}throw new Exception("Online mode is off. Enable it in Settings.");}if(!allowed(feature))throw new Exception(feature+" is disabled in Settings.");if(path.equals("/v1/ask")&&!allowed("ai")||path.startsWith("/v1/kivo/")&&!allowed("messaging")||path.startsWith("/v1/my/")&&!allowed("publishing")||path.startsWith("/v1/ecosystem/")&&!(allowed("cloud")||allowed("community")||allowed("publishing")))throw new Exception("This online feature is disabled.");connection=(HttpURLConnection)new URL("https://nexora-api-production-90da.up.railway.app"+path).openConnection();connections.add(connection);connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(45000);connection.setRequestMethod(method);connection.setRequestProperty("Accept","application/json");String token=token();if(!token.isEmpty())connection.setRequestProperty("Authorization","Bearer "+token);JSObject body=call.getObject("body");if(body!=null){byte[] bytes=body.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>12*1024*1024)throw new Exception("Request is too large.");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");connection.getOutputStream().write(bytes);}int status=connection.getResponseCode();InputStream in=status>=400?connection.getErrorStream():connection.getInputStream();if(in==null)throw new Exception("The server is unavailable.");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){out.write(bytes,0,n);if(out.size()>12*1024*1024)throw new Exception("Response is too large.");}JSONObject data=new JSONObject(out.toString("UTF-8"));if(data.has("token")&&status<400){saveToken(data.getString("token"));data.remove("token");}if(status==401)saveToken("");if(data.has("user")&&status<400)prefs.edit().putString("profile",data.toString()).apply();if((path.equals("/v1/auth/logout")||path.equals("/v1/me")&&method.equals("DELETE"))&&status<400)saveToken("");call.resolve(JSObject.fromJSONObject(data));}catch(Exception e){call.resolve(new JSObject().put("error",e.getMessage()==null?"Could not reach Nexora.":e.getMessage()));}finally{if(connection!=null){connections.remove(connection);connection.disconnect();}}});}
 @PluginMethod public void openSite(PluginCall call){String domain=call.getString("domain","");if(!allowed("nexora")||!domain.matches("[a-z0-9][a-z0-9-]*\\.(nex|vnt|zen|orb|kiv)")){call.resolve(new JSObject().put("error","Enable Online mode and Nexora browsing for a valid address."));return;}android.content.Intent intent=new android.content.Intent(getContext(),IsolatedPageActivity.class);intent.putExtra("site",domain);getActivity().startActivity(intent);call.resolve(new JSObject().put("ok",true));}
 @PluginMethod public void preview(PluginCall call){try{org.json.JSONArray files=call.getArray("files");if(files==null||files.length()>100||files.toString().length()>3000000)throw new Exception("Preview up to 100 files and 2 MB.");boolean index=false;long bytes=0;for(int n=0;n<files.length();n++){JSONObject file=files.getJSONObject(n);String path=file.getString("path");if(path.contains("..")||path.startsWith("/")||path.contains("\\")||path.startsWith(".")||!path.matches("[a-zA-Z0-9_ .-]+(?:/[a-zA-Z0-9_ .-]+)*"))throw new Exception("Invalid preview path.");bytes+=android.util.Base64.decode(file.getString("data"),android.util.Base64.DEFAULT).length;if(bytes>2097152)throw new Exception("Preview files support up to 2 MB.");index|=path.equals("index.html");}if(!index)throw new Exception("Include index.html.");String id=java.util.UUID.randomUUID().toString();IsolatedPageActivity.bundles.put(id,files);android.content.Intent intent=new android.content.Intent(getContext(),IsolatedPageActivity.class);intent.putExtra("bundle",id);getActivity().startActivity(intent);call.resolve(new JSObject().put("url","about:blank"));}catch(Exception e){call.resolve(new JSObject().put("error",e.getMessage()));}}

}
